{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.repeat_decision_eoq as WITH category AS ( SELECT sku_group, category, CASE WHEN LOWER(sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(style) LIKE \'%luxe%\' THEN \'luxe\' WHEN LOWER(style) LIKE \'%core%\' THEN \'core\' WHEN LOWER(category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' WHEN LOWER(style) LIKE \'%revolution%\' THEN \'revolution\' WHEN LOWER(style) LIKE \'%bordeaux%\' THEN \'bordeaux\' ELSE \'Snitch\' END AS l1_category FROM snitch_db.maplemonk.metafields_data QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY status DESC) = 1 ), main_data AS ( SELECT a.*, b.category, b.l1_category, c.p90, cmi.multiplier, a.ros*cmi.multiplier as adjusted_ros, mp.marketplace_split, mp.discount_percentage FROM snitch_db.maplemonk.original_ros_str_eoq a LEFT JOIN category b ON a.sku_group = b.sku_group LEFT JOIN snitch_db.maplemonk.category_l1category_ros_filter_eoq c ON b.category = c.category AND b.l1_category = c.l1_category LEFT JOIN snitch_db.maplemonk.category_month_index cmi ON b.category = cmi.category AND b.l1_category = cmi.l1_category AND MONTH(a.inward_date) = MONTH(cmi.order_month) LEFT JOIN snitch_db.maplemonk.discount_percentage_marketplace_split_eoq mp ON a.sku_group = mp.sku_group ), base_with_lag AS ( SELECT *, CASE WHEN ros >= p90 THEN 1 ELSE 0 END AS ros_above_p90, CASE WHEN adjusted_ros >= p90 THEN 1 ELSE 0 END AS adjusted_ros_above_p90, LAG(ros) OVER (PARTITION BY sku_group ORDER BY inward_freq) AS lag_ros, LAG(adjusted_ros) OVER (PARTITION BY sku_group ORDER BY inward_freq) AS adjusted_lag_ros FROM main_data ), strict_check AS ( SELECT sku_group, COUNT(*) AS total_inwards, COUNT_IF(ros_above_p90 = 1) AS total_p90_hits, COUNT_IF(ros > lag_ros) AS strictly_increasing_ros, COUNT_IF(ros < lag_ros) AS strictly_decreasing_ros, AVG(ros) AS avg_ros, COUNT_IF(adjusted_ros_above_p90 = 1) AS adjusted_total_p90_hits, COUNT_IF(adjusted_ros > lag_ros) AS adjusted_strictly_increasing_ros, COUNT_IF(adjusted_ros < lag_ros) AS adjusted_strictly_decreasing_ros, AVG(adjusted_ros) AS adjusted_avg_ros FROM base_with_lag GROUP BY sku_group ), last_inward_check AS ( SELECT sku_group, MAX(inward_freq) AS last_inward_freq FROM base_with_lag GROUP BY sku_group ), last_inward_flag AS ( SELECT b.sku_group, MAX(CASE WHEN b.inward_freq = l.last_inward_freq AND b.ros_above_p90 = 1 THEN 1 ELSE 0 END) AS is_last_inward_p90, MAX(CASE WHEN b.inward_freq = l.last_inward_freq AND b.adjusted_ros_above_p90 = 1 THEN 1 ELSE 0 END) AS adjusted_is_last_inward_p90 FROM base_with_lag b JOIN last_inward_check l ON b.sku_group = l.sku_group GROUP BY b.sku_group ), sku_group_category AS ( SELECT s.sku_group, CASE WHEN s.total_inwards > 1 AND s.total_p90_hits = s.total_inwards AND s.strictly_increasing_ros = s.total_inwards - 1 THEN \'strictly_increasing\' WHEN s.total_p90_hits = s.total_inwards THEN \'consistent\' WHEN s.avg_ros >= c.p90 AND s.strictly_decreasing_ros < s.total_inwards - 1 THEN \'non_consistent\' WHEN l.is_last_inward_p90 = 1 THEN \'last_inward\' when s.total_inwards > 1 AND s.adjusted_total_p90_hits = s.total_inwards AND s.adjusted_strictly_increasing_ros = s.total_inwards - 1 THEN \'adjusted_strictly_increasing\' WHEN s.adjusted_total_p90_hits = s.total_inwards THEN \'adjusted_consistent\' ELSE \'no\' END AS category_segmentation FROM strict_check s LEFT JOIN last_inward_flag l ON s.sku_group = l.sku_group LEFT JOIN ( SELECT DISTINCT sku_group, p90 FROM main_data ) c ON s.sku_group = c.sku_group ), str_eligible as ( select sku_group, str_eligible from snitch_db.maplemonk.original_ros_str_eoq where inward_freq = total_inwards ), pre_output as ( SELECT b.*, c.category_segmentation, case when discount_percentage >= 0.2 then \'discount_heavy\' else \'non_discount_heavy\' end as discount_placement FROM base_with_lag b LEFT JOIN sku_group_category c ON b.sku_group = c.sku_group ), pre_str_check as ( select sku_group, category_segmentation, discount_placement, case when category_segmentation = \'no\' or discount_placement = \'discount_heavy\' then \'no\' else \'yes\' end as repeat from pre_output qualify row_number() over (partition by sku_group order by inward_date desc) = 1 ) select a.sku_group, a.category_segmentation, a.discount_placement, case when a.repeat = \'yes\' and b.str_eligible = \'no\' then \'no\' else a.repeat end as repeat from pre_str_check a left join str_eligible b on a.sku_group = b.sku_group",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            